        "stage": "derogation_mineure",
        "procedure": null,
        "objet": "2026-011",
        "page": 14,
        "citation": "D’APPROUVER la demande de dérogation mineure 2026-011 pour les immeubles\nsitués aux 360-366 et 398-400, rue Papin, lots 4 813 320 et 4 813 323",
        "anchor": "dérogation mineure 2026-011"
      },
      "reason": "La résolution 2026-04-073 approuve une seule demande identifiée, couvrant les dérogations de profondeur et de superficie des deux lots."
    },
    {
      "op": "add",
      "unit": {
